class Solution {
public:
    bool checkRecord(string s) {
        int absent = 0, late = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == 'A') absent++;
            late = s[i] == 'L' ? late + 1 : 0;
            if (absent >= 2 || late >= 3) return false;
        }
        return true;
    }
};
